{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 동물보호 조례상 1년 전 벌금형을 받은 수의사의 동물복지위원회 위원 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "1년 전 벌금형을 받은 수의사는 서울시 동물복지위원회 위원이 될 수 없습니다. 조례 제5조제11항제4호는 벌금형의 선고를 받고 2년이 경과되지 아니한 사람은 위원이 될 수 없다고 정하고 있습니다. 1년 전 벌금형을 받은 경우는 2년이 경과되지 않았으므로 이 결격사유에 해당합니다. 수의사는 제5조제2항제1호에 따라 위원 위촉 대상이 될 수 있으나, 제5조제11항의 결격사유가 우선 적용됩니다.",
          "b_ids": "동물보호:제5조제11항제4호, 동물보호:제5조제2항제1호, 동물보호:제5조제11항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
